@page "/dashboard"
@rendermode InteractiveServer
@inject Services.WarehouseState WarehouseState
@inject Services.InventoryAlertService AlertService
@inject Services.InventoryAlertState AlertState
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-body">
        <h5 class="card-title">
            Current Site: @GetWarehouseName()
        </h5>
        <p class="card-text">
            Monitoring inventory levels. Polling every 10 seconds.
        </p>
    </div>
</div>

<div class="row">
    <div class="col-md-4">
        <div class="card @(AlertState.LowStockCount > 0 ? "border-danger" : "border-success")">
            <div class="card-body text-center">
                <h2 class="@(AlertState.LowStockCount > 0 ? "text-danger" : "text-success")">
                    @AlertState.LowStockCount
                </h2>
                <p class="card-text">Low Stock Alerts</p>
            </div>
        </div>
    </div>
</div>

@code {
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private Action? _warehouseHandler;
    private Action? _alertHandler;

    protected override void OnInitialized()
    {
        _warehouseHandler = () => InvokeAsync(OnWarehouseChanged);
        WarehouseState.OnChange += _warehouseHandler;

        _alertHandler = () => InvokeAsync(StateHasChanged);
        AlertState.OnChange += _alertHandler;
    }

    protected override Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            StartPolling();
        }
        return Task.CompletedTask;
    }

    private void StartPolling()
    {
        StopPolling();
        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fetch immediately on start
        await FetchAlertCountAsync();

        try
        {
            while (await _timer!.WaitForNextTickAsync(ct))
            {
                await FetchAlertCountAsync();
            }
        }
        catch (OperationCanceledException) { }
    }

    private async Task FetchAlertCountAsync()
    {
        var count = await AlertService.GetLowStockCountAsync(WarehouseState.SelectedWarehouseId);
        // Update shared state — this notifies ALL subscribers (sidebar badge, etc.)
        AlertState.UpdateCount(count);
    }

    private async Task OnWarehouseChanged()
    {
        // Warehouse changed — immediately re-fetch alerts for the new site
        await FetchAlertCountAsync();
        StateHasChanged();
    }

    private string GetWarehouseName()
    {
        return Services.WarehouseState.AvailableWarehouses
            .FirstOrDefault(w => w.Id == WarehouseState.SelectedWarehouseId).Name ?? "Unknown";
    }

    private void StopPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    public void Dispose()
    {
        StopPolling();

        if (_warehouseHandler is not null)
            WarehouseState.OnChange -= _warehouseHandler;

        if (_alertHandler is not null)
            AlertState.OnChange -= _alertHandler;
    }
}

